# Blender/bpy port of examples/import-mesh.lms (generated by docs/tutorial/blender/lms2py.py, reviewed by hand)
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import lmb_bpy

scene = lmb_bpy.Scene()
mesh = scene.import_obj("tests/fixtures/tetra.obj")
scene.expect_int(mesh.vertex_count(), 4)
scene.expect_int(mesh.triangle_count(), 4)
stl = scene.import_stl("tests/fixtures/one-triangle.stl")
scene.expect_int(stl.vertex_count(), 3)
scene.expect_int(stl.triangle_count(), 1)
binary_stl = scene.import_stl("tests/fixtures/one-triangle-binary.stl")
scene.expect_int(binary_stl.vertex_count(), 3)
scene.expect_int(binary_stl.triangle_count(), 1)
lmb_bpy.done()
